# ==============================================================================
# ASCII block legend
# ==============================================================================

def _ascii_bar(ret: float) -> str:
    """
    Return ASCII block chars representing the return level.
      ████  > +3%
      ███   +1–3%
      ██    0–1%
      ▒     -1–0%
      ░     -3–-1%
      ▓     < -3%
    """
    if   ret >=  0.03: return '████'
    elif ret >=  0.01: return '███ '
    elif ret >=  0.00: return '██  '
    elif ret >= -0.01: return '▒   '
    elif ret >= -0.03: return '░   '
    else:              return '▓   '


def _return_str(ret: float) -> str:
    return f"{ret:+.1%}"


