        # Day 2: Hold
        {},
        # Day 3: Exit longs
        {"AAPL": {"action": "sell", "quantity": 50}, "TSLA": {"action": "sell", "quantity": 30}},
        # Day 4: Cover remaining shorts
        {"MSFT": {"action": "cover", "quantity": 25}},
